class Solution:
    def minSwapsToPalindrome(self, word: str) -> int:
        s, moves = list(word), 0
        while len(s) > 1:
            j = len(s) - 1
            while s[j] != s[0]:
                j -= 1
            if j == 0:
                moves += len(s) // 2
                s.pop(0)
            else:
                moves += len(s) - 1 - j
                s.pop(j)
                s.pop(0)
        return moves

