class Solution {
    public int minSwapsToPalindrome(String word) {
        StringBuilder s = new StringBuilder(word);
        int moves = 0;
        while (s.length() > 1) {
            int j = s.length() - 1;
            while (s.charAt(j) != s.charAt(0)) j--;
            if (j == 0) {
                moves += s.length() / 2;
                s.deleteCharAt(0);
            } else {
                moves += s.length() - 1 - j;
                s.deleteCharAt(j);
                s.deleteCharAt(0);
            }
        }
        return moves;
    }
}

