class Solution {
public:
    int minSwapsToPalindrome(string& word) {
        string s = word;
        int moves = 0;
        while (s.size() > 1) {
            int j = s.size() - 1;
            while (s[j] != s[0]) j--;
            if (j == 0) {
                moves += s.size() / 2;
                s.erase(0, 1);
            } else {
                moves += s.size() - 1 - j;
                s.erase(j, 1);
                s.erase(0, 1);
            }
        }
        return moves;
    }
};

