int minSwapsToPalindrome(char* word) {
    int n = strlen(word), lo = 0, moves = 0;
    char* s = malloc(n + 1);
    memcpy(s, word, n + 1);
    while (n - lo > 1) {
        int j = n - 1;
        while (s[j] != s[lo]) j--;
        if (j == lo) {
            moves += (n - lo) / 2;
            lo++;
        } else {
            moves += n - 1 - j;
            memmove(s + j, s + j + 1, n - 1 - j);
            n--;
            lo++;
        }
    }
    free(s);
    return moves;
}
